\label{lem:tail}
Let $f,h\in L^1(\R^2)$ be real-valued, with $h\ge0$ almost everywhere.
Let $\chi_n$ be measurable real functions such that
$|\chi_n(x)|\le B$ for every $n\in\mathbb N$ and $x\in\R^2$,
for a fixed $B\ge0$, and $\chi_n\to1$ almost everywhere.
Suppose that, for a fixed $C\ge0$,
\begin{equation}\label{eq:tail-hypothesis}
 \left|\int f\chi_n\dd\right|
   \le C\left(\int_{\{|x|\ge n\}}h\dd\right)^{1/2}
       \qquad(n\in\mathbb N).
\end{equation}
Then $\int f\dd=0$.

\label{thm:cancellation}
Let $f\in L^1(\R^2;\R)$ and $V\in L^2(\R^2;\R^2)$.
Suppose that $f=\Div V$ in distributions, that is,
\begin{equation}\label{eq:distributional}
 \int f\varphi\dd=-\int V\cdot\nabla\varphi\dd
       \qquad\text{for every }\varphi\in C_c^\infty(\R^2).
\end{equation}
Then $\int_{\R^2}f\dd=0$.

\label{prop:physical-energy}
Under the regularity condition above,
\begin{equation}\label{eq:energy-balances}
 K'+\mathcal D=\int Pd\dd,\qquad
 H'=\mathcal D-\int Pd\dd,\qquad E'=0.
\end{equation}
If the interval includes zero, with the stated initial traces, then
\begin{equation}\label{eq:energy-small}
 K(t)+H(t)=E_0,\qquad
 \norm{\sqrt\rho u}{2}^2\le2E_0,\qquad
 \norm{P}{1}\le\frac{R}{c_v}E_0.
\end{equation}
For any two times $s<t$ in the interval,
\begin{equation}\label{eq:kinetic-pressure}
 K(t)+\frac{\mu}{2}\int_s^t\norm{\nabla u}{2}^2\dt
 \le K(s)+\frac1\mu\int_s^t\norm{P}{2}^2\dt.
\end{equation}

\label{prop:pressure-feedback}
Under the same regularity condition,
\begin{align}
 H'+\frac1\nu\norm{P}{2}^2
     &=\mathcal D-\frac1\nu\int PG\dd,\label{eq:internal-flux}\\
 K'+\frac12\mathcal D
     &\le\frac1{2\nu}\norm{P}{2}^2.\label{eq:kinetic-flux}
\end{align}
Consequently,
\begin{equation}\label{eq:pressure-spacetime}
 \frac1{2\nu}\int_s^t\norm{P}{2}^2\dt
 \le H(s)+\int_s^t\mathcal D\dt
                 +\frac1{2\nu}\int_s^t\norm{G}{2}^2\dt.
\end{equation}

\label{prop:pressure-square}
Under the regularity condition of Section~\ref{sec:energy},
\begin{align}
 \frac d{dt}\norm{P}{2}^2+\frac{1+2\beta}{\nu}\int P^3\dd
 ={}&-\frac{1+2\beta}{\nu}\int P^2G\dd+2\beta\int PQ\dd\nonumber\\
 &+2\beta\kappa\int P\Delta\theta\dd,\label{eq:pressure-square}\\
 \int P\Delta\theta\dd
 ={}&-R\int\rho|\nabla\theta|^2\dd
       -R\int\theta\nabla\rho\cdot\nabla\theta\dd.
       \label{eq:conduction-pressure}
\end{align}

\label{prop:thermal}
Under the regularity condition of Section~\ref{sec:energy},
\begin{equation}\label{eq:thermal-identity}
 \frac{c_v}{2}X'+\kappa Z=J-R\int\rho\theta^2d\dd.
\end{equation}
Writing $U=\norm{u}{\infty}$ and $M=\norm{\rho}{\infty}$, for every
$\varepsilon>0$ one has
\begin{equation}\label{eq:heating-bound}
 J\le\varepsilon(V+Z)+C_\varepsilon U^2\{N+(1+M)X\}
                  +C\norm{d}{\infty} X.
\end{equation}

\label{prop:specific}
Under the regularity condition of Section~\ref{sec:energy},
\begin{equation}\label{eq:specific-equation}
 \rho\dot w=\kappa\Delta\theta+\Div F.
\end{equation}
The functional $Y$ satisfies
\begin{align}
 \frac12Y'+\kappa c_v\norm{\nabla\theta}{2}^2
 &=-\kappa\int\nabla k\cdot\nabla\theta\dd
       -\int F\cdot(c_v\nabla\theta+\nabla k)\dd,
       \label{eq:specific-theta}\\
 \frac12Y'+a_\kappa\norm{\nabla w}{2}^2
 &=\int(a_\kappa\nabla k-F)\cdot\nabla w\dd.
       \label{eq:specific-w}
\end{align}
In particular,
\begin{equation}\label{eq:specific-bound}
 \begin{split}
 Y'+a_\kappa\norm{\nabla w}{2}^2
 &\le a_\kappa^{-1}\norm{a_\kappa\nabla k-F}{2}^2\\
 &\le C\int|u|^2(|\nabla u|^2+P^2)\dd .
 \end{split}
\end{equation}
With $N$ as in \eqref{eq:thermal-notation},
$U=\norm{u}{\infty}$, and $M=\norm{\rho}{\infty}$,
\begin{equation}\label{eq:specific-gronwall}
 \begin{split}
 Y(t)+a_\kappa\int_s^t\norm{\nabla w}{2}^2\dt
 \le{}&\left(Y(s)+C\int_s^tU^2N\dt\right)\\
 &{}\times\exp\left(C\int_s^tMU^2\dt\right).
 \end{split}
\end{equation}

\label{thm:obstruction}
Assume \eqref{eq:parameters}, \eqref{eq:data},
\eqref{eq:compatibility}, and \eqref{eq:compactdata}.
If a solution in the sense of Definition~\ref{def:solution} exists on
$[0,T_*)$, then for every $0\le t<T_*$,
\begin{equation}
 I_0+2J_0t+2\beta E_0t^2
       \le\int\rho(t,x)|x|^2\dd\le ML^2.
 \label{eq:mainbound}
\end{equation}
Consequently,
\begin{equation}
 T_*\le
 \frac{-J_0+\sqrt{J_0^2+2\beta E_0(ML^2-I_0)}}
      {2\beta E_0}<\infty.
 \label{eq:lifespan}
\end{equation}
In particular, no global solution satisfying the stated class on
every finite interval exists for these data.

\label{prop:fixedsupport}
Let a solution satisfy Definition~\ref{def:solution} on $[0,T_*)$,
and suppose that $\supp\rho_0\subset\overline{B_L}$. Then
\begin{equation}
 \begin{gathered}
 \supp\rho(t)\subset\overline{B_L}\quad(0\le t<T_*),\\
 u(t)=\theta(t)=0\quad\hbox{on }\R^2\setminus\overline{B_L}
 \end{gathered}
 \label{eq:fixedsupport}
\end{equation}
for almost every $t\in(0,T_*)$. The density assertion holds for its
continuous spatial representative.

\label{prop:energy}
Under the hypotheses of Theorem~\ref{thm:obstruction}, set
\[
 K(t)=\frac12\int\rho|u|^2\dd,\qquad
 U(t)=c_v\int\rho\theta\dd.
\]
For each $T<T_*$ these quantities have absolutely continuous
representatives on $[0,T]$, with
\begin{equation}
 \begin{aligned}
 K(0)&=\frac12\int\rho_0|u_0|^2\dd,\qquad
 U(0)=c_v\int\rho_0\theta_0\dd,\\
 K'(t)&=-\int Q(u)\dd+\int P\Div u\dd,\\
 U'(t)&=\int Q(u)\dd-\int P\Div u\dd
 \end{aligned}\label{eq:energyidentities}
\end{equation}
for almost every $t$. In particular,
\begin{equation}
 K(t)+U(t)=E_0,\qquad K(t),U(t)\ge0,\qquad 0\le t<T_*.
 \label{eq:energyconservation}
\end{equation}
Moreover, $\int\rho(t)\dd=M$ for all $t<T_*$.

\label{cor:smallenergy}
Fix the parameters in \eqref{eq:parameters}, $a>1$, $q>2$,
$\eta_0>0$, and a mass $M>0$. There is a family
$(\rho_0^\varepsilon,u_0^\varepsilon,\theta_0^\varepsilon)$,
$0<\varepsilon\le1$, of smooth compactly supported data satisfying
\eqref{eq:data}--\eqref{eq:compatibility} such that
\begin{equation}
 \begin{gathered}
 \int\rho_0^\varepsilon\dd=M,\qquad
 \supp\rho_0^\varepsilon\subset\overline{B_1},\\
 E_0^\varepsilon>0,\qquad E_0^\varepsilon\longrightarrow0.
 \end{gathered}
 \label{eq:familyproperties}
\end{equation}
The density is independent of $\varepsilon$. Every norm displayed
in \eqref{eq:data}, as well as $\norm{g^\varepsilon}{2}$, has a
common finite upper bound. No member of the family admits a global
solution in Definition~\ref{def:solution}.
